/**
 * PROTOTYPE — not for release.
 *
 * Stands in for a real per-tint plate store so the photographed-lens approach
 * can be judged before it is built. Images live in frontend/public/tint-proto,
 * with their dimensions in tint-proto-manifest.json because the supplied sets
 * were exported at different sizes.
 *
 * Two sets are staged so they can be compared directly:
 *   default    — generated by scripts/generate-tinted-plates.mjs, which recolours
 *                the live plate, so the frame's shape and hardware are the real
 *                product's by construction
 *   ?yours=1   — the hand-retouched exports
 *   ?noproto=1 — neither; falls back to procedural tinting
 *
 * The generated set is the default because it is the only one that holds the
 * frame still. The hand-retouched exports were cropped per tint — PK002 alone
 * ranges from 1144x390 to 2037x772 — so changing tint swaps to a differently
 * cropped photograph and the frame appears to resize. They also cover 125 of the
 * 240 combinations, and the rest fall through to procedural tinting, which
 * changes the look again. Neither is a fault in the exports; they were made to
 * show colour, not to be flipped between.
 */
import manifest from "./tint-proto-manifest.json";

interface TintedPlate {
  file: string;
  w: number;
  h: number;
}

const SETS = manifest as {
  yours: Record<string, TintedPlate>;
  generated: Record<string, TintedPlate>;
};

export function resolveTintedPlate(
  frameName: string | undefined,
  tintHex: string | undefined,
  view: string,
): TintedPlate | null {
  const search = typeof window !== "undefined" ? window.location.search : "";
  if (search.includes("noproto")) return null;
  if (!frameName || !tintHex) return null;
  if (view !== "front" && view !== "side") return null;
  const slug = frameName.trim().toLowerCase();
  const hex = tintHex.replace("#", "").toLowerCase();
  const set = search.includes("yours") ? SETS.yours : SETS.generated;
  const found = set[`${slug}|${view}|${hex}`];
  if (!found) return null;
  return { ...found, file: `${import.meta.env.BASE_URL}tint-proto/${found.file}` };
}
